<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {fixed,pct} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import BlendMetrics from '../components/BlendMetrics.vue';import RecipeBars from '../components/RecipeBars.vue';import QualityTable from '../components/QualityTable.vue';import SampleCloud from '../components/SampleCloud.vue';const selected=ref(route.value.query.get('run')||'demo-run'),action=ref('核查名义配方约束余量与固定配方LHS通过数；线性混合与独立均匀扰动只作模拟假设，不据此直接认证工业质量。'),notice=ref('');watch(()=>route.value.query.get('run'),v=>{selected.value=v||'demo-run'});const {error,busy,act}=useTask();let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result);const joint=computed(()=>result.value?.robustness?.joint);const jointPairs=computed(()=>{const j=joint.value;if(!j)return[];const out=[];for(let a=0;a<j.keys.length;a++)for(let b=a+1;b<j.keys.length;b++)out.push({ka:j.keys[a],kb:j.keys[b],target:j.target[a][b],actual:j.actual[a][b],n:j.pair_counts[a][b]});return out.sort((x,y)=>Math.abs(y.target)-Math.abs(x.target)).slice(0,12)});function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='配方复核已提交，等待管理员批准。'})}</script><template><PageHeading index="05 / 运行底稿" title="看名义约束，也看固定配方的失败样本。" note="求解器只优化名义参数一次，LHS样本只重新评价固定比例。不可行没有配方，也没有伪造的模拟结果。"/><div class="result-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{r.id==='demo-run'?'八原浆基线':r.id.slice(0,8)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><Notice v-if="run?.status==='infeasible'" :message="result.lp.reason"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="后台worker正在求名义配方并评价固定比例的LHS扰动，每两秒刷新。"/><template v-if="run?.status==='completed'&&result"><BlendMetrics :result="result"/><p v-if="result.inputs?.mode" class="method-note">输入成套冻结：{{result.inputs.dataset_name}} · {{result.inputs.spec_name}}<template v-if="result.inputs.mode==='joint'"> · 校准 {{result.inputs.calibration_name}}（源v{{result.inputs.calibration_source_version}}）</template><template v-else> · 独立均匀扰动</template> · {{result.inputs.frozen_at}}</p><div class="formula-overview"><section><h2>名义配方比例</h2><RecipeBars :rows="result.lp.shares"/></section><section><h2>固定配方扰动分布</h2><SampleCloud :result="result"/><QualityTable :rows="result.lp.qualities"/><p class="method-note">{{result.robustness.assumption}}</p><p class="method-note">边界比较绝对容差 {{result.robustness.comparison_tolerance}}（各属性自身单位）；成本{{result.robustness.perturb_cost?'同时扰动':'固定'}}，LHS {{result.robustness.dimension_count}}维，seed={{result.robustness.seed}}；零宽度维变换后为常量。</p></section></div><section v-if="joint" class="joint-section"><h2>联合扰动校准底稿</h2><div class="metrics"><div><small>目标↔实际最大偏差</small><strong>{{fixed(joint.max_abs_deviation,3)}}</strong><span>Spearman秩相关</span></div><div><small>平均绝对偏差</small><strong>{{fixed(joint.mean_abs_deviation,3)}}</strong><span>{{joint.keys.length}}个非常量维度</span></div><div><small>最小成对有效样本</small><strong>{{joint.min_pair_n}}</strong><span>缺测不补零 · 源v{{joint.source_version}}</span></div></div><p class="method-note">{{joint.method}}；校准 {{joint.calibration_name}}，相关矩阵最小特征值 {{fixed(joint.min_eigenvalue,4)}}。<template v-if="joint.constant_keys?.length">常量维度（零扰动宽度）不参与相关诱导：{{joint.constant_keys.join('、')}}。</template></p><div class="table-wrap"><table><thead><tr><th>维度A</th><th>维度B</th><th>目标ρ</th><th>实际ρ</th><th>有效样本n</th></tr></thead><tbody><tr v-for="p in jointPairs" :key="p.ka+p.kb"><td>{{p.ka}}</td><td>{{p.kb}}</td><td>{{fixed(p.target,3)}}</td><td>{{fixed(p.actual,3)}}</td><td>{{p.n}}</td></tr></tbody></table></div><p class="method-note">按|目标ρ|最大的前12对展示；完整矩阵随结果JSON保存。目标来自配对实测校准，实际为本次LHS重排后的样本秩相关。</p></section><div class="result-columns"><section><h2>扰动样本预览</h2><div class="table-wrap"><table><thead><tr><th>序号</th><th>强度</th><th>白度</th><th>回收率</th><th>成本</th><th>全部合规</th></tr></thead><tbody><tr v-for="s in result.robustness.samples.slice(0,16)" :key="s.index"><td>{{s.index}}</td><td>{{fixed(s.strength)}}</td><td>{{fixed(s.whiteness)}}</td><td>{{pct(s.recycled)}}</td><td>{{fixed(s.cost)}}</td><td>{{s.compliant?'是':'否'}}</td></tr></tbody></table></div></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>提交配方复核</h2><label>复核说明<textarea v-model="action" required minlength="8" rows="7"></textarea></label><button :disabled="busy">提交配方复核</button><p class="success" v-if="notice">{{notice}}</p></form></div></template></template>
